<div class="intro-line"><p>Seluruh entri Excel ODS tetap tercatat. Data referensi lintas kewenangan diberi penanda agar tidak bercampur dengan daftar kerja kabupaten.</p><?php if ($can_create): ?><a class="button button-dark" href="<?= site_url('admin/koperasi/tambah') ?>">+ Tambah koperasi</a><?php endif; ?></div>
<section class="panel table-panel"><form class="filterbar" method="get" action="<?= site_url('admin/koperasi') ?>"><label class="search-field"><span>Cari koperasi</span><input type="search" name="q" value="<?= h($p['q']) ?>" placeholder="Nama, NIK, badan hukum"></label><label><span>Lingkup</span><select name="scope"><option value="">Semua</option><option value="kabupaten" <?= $scope==='kabupaten'?'selected':'' ?>>Daftar kabupaten</option><option value="referensi" <?= $scope==='referensi'?'selected':'' ?>>Referensi lintas kewenangan</option></select></label><label><span>Jenis</span><select name="type"><option value="">Semua jenis</option><?php foreach ($types as $x): ?><option value="<?= $x['id'] ?>" <?= (string)$type===(string)$x['id']?'selected':'' ?>><?= h($x['name']) ?></option><?php endforeach; ?></select></label><label><span>Kecamatan</span><select name="district"><option value="">Semua kecamatan</option><?php foreach ($districts as $x): ?><option value="<?= $x['id'] ?>" <?= (string)$district===(string)$x['id']?'selected':'' ?>><?= h($x['name']) ?></option><?php endforeach; ?></select></label><label><span>Status data</span><select name="record_status"><option value="" <?= $record_status===''?'selected':'' ?>>Aktif</option><option value="arsip" <?= $record_status==='arsip'?'selected':'' ?>>Arsip</option><option value="semua" <?= $record_status==='semua'?'selected':'' ?>>Semua</option></select></label><label><span>Status ODS</span><select name="status"><option value="">Semua</option><option value="Aktif" <?= $p['status']==='Aktif'?'selected':'' ?>>Aktif</option><option value="Tidak Aktif" <?= $p['status']==='Tidak Aktif'?'selected':'' ?>>Tidak Aktif</option><option value="Belum diverifikasi" <?= $p['status']==='Belum diverifikasi'?'selected':'' ?>>Belum diverifikasi</option></select></label><label><span>Per halaman</span><select name="per_page"><?php foreach (array(10,25,50,100) as $n): ?><option value="<?= $n ?>" <?= $p['per_page']===$n?'selected':'' ?>><?= $n ?></option><?php endforeach; ?></select></label><button class="button button-dark button-small" type="submit">Terapkan</button><a class="button button-quiet button-small" href="<?= site_url('admin/koperasi') ?>">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Nama koperasi</th><th>NIK / badan hukum</th><th>Jenis</th><th>Kecamatan</th><th>Lingkup</th><th></th></tr></thead><tbody><?php foreach ($rows as $r): ?><tr><td><a class="table-name" href="<?= site_url('admin/koperasi/'.$r['id']) ?>"><?= h($r['name']) ?></a><small class="cell-sub"><?= h($r['ods_status']) ?></small></td><td class="mono"><?= h($r['nik']) ?><small class="cell-sub"><?= h($r['legal_number']) ?></small></td><td><?= h($r['type_name']) ?></td><td><?= h($r['district_name']) ?></td><td><span class="pill <?= $r['reference_only']?'pill-muted':'pill-green' ?>"><?= h(label_scope($r['authority_scope'])) ?></span></td><td><a class="row-link" href="<?= site_url('admin/koperasi/'.$r['id']) ?>">Lihat →</a></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="6" class="empty-cell">Tidak ada koperasi yang sesuai filter.</td></tr><?php endif; ?></tbody></table></div><?php $this->load->view('partials/pagination'); ?></section>
